settings.custom_css:
.frcp-wishlist-btn__icon svg {
  display: none;
}
.frcp-wishlist-btn__icon::before {
  content: "+";
  display: inline-block;
  transition: transform 0.3s ease, opacity 0.3s ease;
  font-size: 1.375rem;
}

.frcp-wishlist-btn--add .frcp-wishlist-btn__icon::before {
  content: "+";
  transform: rotate(0deg);
  opacity: 1;
  animation: icon-fade-in 0.3s forwards;
  font-size: 1.375rem;
}

.frcp-wishlist-btn--remove .frcp-wishlist-btn__icon::before {
  content: "−";
  transform: rotate(90deg);
  opacity: 1;
  animation: icon-fade-in 0.3s forwards;
  font-size: 1.5rem;
  margin-top: -2px;
}

@keyframes icon-fade-in {
  0% {
    opacity: 0;
    transform: scale(0.8);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

.frcp-wishlist-btn__icon {
  transition: transform 0.3s ease, opacity 0.3s ease;
}
